import {
  IsString,
  IsNotEmpty,
  IsOptional,
  IsDateString,
} from 'class-validator';

export class CreateEmployeeDto {
  // Generated by the server; any client value is ignored.
  @IsOptional()
  @IsString()
  code?: string;

  @IsString()
  @IsNotEmpty()
  fullName: string;

  @IsString()
  @IsOptional()
  nationalId?: string;

  @IsString()
  @IsOptional()
  jobTitle?: string;

  @IsDateString()
  @IsOptional()
  hireDate?: string;
}
